 if u['equivalent_units'] is not None:body+='<p>Taille préparée : <strong>'+n(u['equivalent_units'],3)+' unités logiques</strong>. COCOMO avant arrondi : '+n(u['raw_proposal_jh'],2)+' JH. Pas d’arrondi : '+n(u['rounding_jh'])+' JH.</p>'
