  body+='<p>Configurations : '+n(d['configuration_units'])+' unités. Les schémas et structures de service sont ceux du Java actuel.</p><ul>'+''.join('<li><strong>'+E(b['id'])+'</strong> : '+E(b['reason'])+'</li>' for b in d['blocks'])+'</ul>'
